// decodeValue decodes an element into its Value implementation.
func decodeValue(e *treetext.Element) (Value, error) {
	switch e.Head {
	case "Adapt":
		return decodeAdapt(e)
	case "Apply":
		return decodeApply(e)
	case "AssocConstValue":
		return decodeAssocConstValue(e)
	case "Await":
		return decodeAwait(e)
	case "BoolLiteral":
		return decodeBoolLiteral(e)
	case "Call":
		return decodeCall(e)
	case "CollectionLiteral":
		return decodeCollectionLiteral(e)
	case "Conversion":
		return decodeConversion(e)
	case "DatetimeLiteral":
		return decodeDatetimeLiteral(e)
	case "DurationLiteral":
		return decodeDurationLiteral(e)
	case "EnumMemberValue":
		return decodeEnumMemberValue(e)
	case "FieldAccess":
		return decodeFieldAccess(e)
	case "FuncCall":
		return decodeFuncCall(e)
	case "FuncLiteral":
		return decodeFuncLiteral(e)
	case "IntLiteral":
		return decodeIntLiteral(e)
	case "LocalRef":
		return decodeLocalRef(e)
	case "MasterRelation":
		return decodeMasterRelation(e)
	case "NullValue":
		return decodeNullValue(e)
	case "ParamRef":
		return decodeParamRef(e)
	case "RangeLit":
		return decodeRangeLit(e)
	case "RecordValue":
		return decodeRecordValue(e)
	case "Reference":
		return decodeReference(e)
	case "RelationCount":
		return decodeRelationCount(e)
	case "SelfValue":
		return decodeSelfValue(e)
	case "StaticCall":
		return decodeStaticCall(e)
	case "StringLiteral":
		return decodeStringLiteral(e)
	case "Ternary":
		return decodeTernary(e)
	case "TypeValue":
		return decodeTypeValue(e)
	case "Unresolved":
		return decodeUnresolved(e)
	default:
		return nil, fmt.Errorf("treetext: line %d: %s is not a known Value", e.Line, e.Head)
	}
}

// decodeValueField decodes one Value-typed field: the nil marker or the node.
func decodeValueField(f treetext.Field) (Value, error) {
	if f.Inline == treetext.Nil {
		return nil, nil
	}
	if f.Node == nil {
		return nil, fmt.Errorf("treetext: line %d: field %s: expected a node", f.Line, f.Name)
	}
	return decodeValue(f.Node)
}

